		ForwardingConsol currentSelectedConsol = null;

		void UpdateValuesFromConsolForBinding(ForwardingConsol consol = null)
		{
			currentSelectedConsol?.CalculationWrapper.MarkAsUnbound();
			currentSelectedConsol = consol ?? ConsolModuleButtonGrid.InnerGrid.ListManager.GetCurrent() as ForwardingConsol;
			currentSelectedConsol?.CalculationWrapper.MarkAsBound();

			UpdateWeightUtilisationPercentageValue(currentSelectedConsol);
			UpdateVolumeUtilisationPercentageValue(currentSelectedConsol);
			UpdateCostFreePercentageValue(currentSelectedConsol);
			UpdateExcessWeightLabels(currentSelectedConsol);
			UpdateVolumeWeightLabels(currentSelectedConsol);
		}

		void UpdateWeightUtilisationPercentageValue(ForwardingConsol consol)
		{
			if (consol != null)
			{
				WeightUtilisationPercentageBar.SetValue(consol.Density.WeightUtilisationPercentage);
			}
			else
			{
				WeightUtilisationPercentageBar.ResetValues();
			}
		}

		void UpdateVolumeUtilisationPercentageValue(ForwardingConsol consol)
