		void UpdateExcessWeightLabels(ForwardingConsol consol)
		{
			if (consol != null)
			{
				ZString label;

				if (consol.IsConsolChargeableByWeight)
				{
					label = consol.Density.IsActualExcess
						? Res.GetString("ConsolDashboard|1d572fd0-cc18-4d55-91cc-e7057972cfec", "Excess Actual Wgt.")
						: Res.GetString("ConsolDashboard|0758cbb1-ef1c-4830-a4e9-441bbf49cbb4", "Excess Vol. Wgt.");
				}
				else
				{
					label = consol.Density.IsActualExcess
						? Res.GetString("ConsolDashboard|855cfb04-c27f-411c-93f8-8a6e956e1a5a", "Excess Actual Vol.")
						: Res.GetString("ConsolDashboard|4c3f1a8d-ccd9-403a-a84c-c58e1e52c978", "Excess Wgt. Vol.");
				}

				ExcessWeightVolumeCalcEdit.GetExtension<ILabelCaptionRenderer>().Caption = label;
			}
		}

