		void CarrierContractsAndAllocationsMenuItem_Click(object sender, EventArgs e)
		{
			if (Dashboard.HasUnsavedChanges)
			{
				Globals.Message.ShowInformation(Res.GetString("b71c664f-7efe-6999-4d26-2773503108a3",
					"Please save any changes on the Consolidations Planning Board to load Carrier Contract & Allocations for Current Consol."));

				return;
			}

			var selectedConsolidations = ConsolModuleButtonGrid.InnerGrid.SelectedElements.OfType<ForwardingConsol>().ToArray();
			if (selectedConsolidations.Length == 1)
			{
				var selectedConsol = selectedConsolidations[0];
				var configurationFactory = new ConsolDashboardContractAllocationConfiguration(selectedConsol);
				var attachFormFactory = ObjectFactory.Get<IContractAndAllocationsAttachFormFactory>();
				var attachForm = attachFormFactory.CreateForm(configurationFactory) as ZForm;

				ZFormModaliser.ShowDialogAndDispose(attachForm);
				return;
			}

			Globals.Message.ShowInformation(Res.GetString("f0f012d7-7537-cba1-4f3a-3b502848d3fe",
								"Please select a single Consolidation."));
		}

		#region View Measurements

		void ViewMeasurements(ForwardingShipment[] selectedShipments)
		{
			if (selectedShipments.Length == 0)
			{
				Globals.Message.Show(Res.GetString("3a506286-ce99-c58b-4df1-b5963eabee78", "Please select a shipment."),
					Res.GetString("24dc728c-66c4-b199-4222-40a3e7f97a5c", "Select Shipment"), MessageBoxButtons.OK, MessageBoxIcon.Warning);
			}
			else
			{
				var title = Res.GetString("76ecca0d-74db-bdad-46f2-5320e3d5264c", "View Measurements");
				var shipmentMeasurementDescription = ShipmentMeasurementsHelper.GetMeasurements(selectedShipments);
				ShipmentViewMeasurementsForm.ShowDialog(title, shipmentMeasurementDescription);
			}
		}

