		void ShowEditFormForCurrentRowIfAllowed<TParent>(ZGrid grid, ControllerID controllerID)
			where TParent : BusinessObject
		{
			if (Dashboard.HasUnsavedChanges)
			{
				Globals.Message.ShowInformation(Res.GetString("10a5be43-9b2b-4a48-b236-4609f32066c3",
					"Please save Planning Board to be able to open Edit form"));

				return;
			}

			var currentBusinessObject = grid?.ListManager?.GetCurrent() as TParent;
			if (currentBusinessObject != null)
			{
				var controller = ZControllerFactory.Create(controllerID);
				controller.ShowChildrenAsDialog = true;
				controller.ShowEditForm(currentBusinessObject);
			}
		}

