		#region Create New Consol

		void CreateNewConsolButton_Click(object sender, EventArgs e)
		{
			CreateNewConsol();
		}

		void CreateNewConsol()
		{
			var selectedShipments = GetSelectedStandaloneShipments();
			if (!selectedShipments.Any())
			{
				Globals.Message.ShowInformation(Res.GetString("0278c104-eb0b-4293-b9c6-2ad0c43d18eb", "Please select shipment(s) first"));
				return;
			}

			var consolCreationFactory = new BusinessObjectFactory()
			{
				NameForDebugging = "ConsolDashboard's Factory for New Consol"
			};

			var consol = Dashboard.CreateConsol(consolCreationFactory, selectedShipments.Select(shipment => shipment.PK));

			var controller = ZControllerFactory.Create(ControllerIDs.JobConsol);
			controller.ShowChildrenAsDialog = true;
			controller.ShowFormForNewEntity(consol);

			if (consol.IsInDatabase)
			{
				Dashboard.AddConsols(new[] { consol });
				Dashboard.Shipments.RemoveRange(selectedShipments.Where(shipment => shipment != null));
			}
		}

		#endregion

		#region Attach

		void AttachButton_Click(object sender, EventArgs e)
		{
			AttachShipments();
		}

		void AttachShipments()
		{
			var selectedConsols = GetSelectedConsols().Take(2).ToArray();
			if (selectedConsols.Length != 1)
			{
				Globals.Message.ShowInformation(Res.GetString("bf8d8237-ead6-4466-b372-10b6e440d104", "Please select a single consol first"));
				return;
			}

			var selectedShipments = GetSelectedStandaloneShipments();
			if (!selectedShipments.Any())
			{
				Globals.Message.ShowInformation(Res.GetString("0278c104-eb0b-4293-b9c6-2ad0c43d18eb", "Please select shipment(s) first"));
				return;
			}

			var currentConsol = selectedConsols.First();
			var selectedShipmentsList = selectedShipments.ToList();
			if (!CheckAttachMasterSub(currentConsol, selectedShipmentsList))
			{
				return;
			}

			var attachResult = Dashboard.TryAttach(currentConsol, selectedShipmentsList);

			if (attachResult.HasErrors)
			{
				Globals.Message.ShowError(attachResult.Errors);
			}

			UpdateValuesFromConsolForBinding(currentConsol);
			UpdateActionButtonsStatus();
		}

