		#region Detach

		void DetachButton_Click(object sender, EventArgs e)
		{
			DetachShipments();
		}

		void DetachShipments()
		{
			var selectedConsols = GetSelectedConsols().Take(2).ToArray();
			if (selectedConsols.Length != 1)
			{
				Globals.Message.ShowInformation(Res.GetString("bf8d8237-ead6-4466-b372-10b6e440d104", "Please select a single consol first"));
				return;
			}

			var selectedCurrentConsolShipments = GetSelectedCurrentConsolShipments();
			if (!selectedCurrentConsolShipments.Any())
			{
				Globals.Message.ShowInformation(Res.GetString("5673bc7d-cbe3-46ad-b0b6-641d86ca5c62", "Please select current consol's shipment(s) first"));
				return;
			}

			var currentConsol = selectedConsols.First();
			var selectedShipmentsList = selectedCurrentConsolShipments.ToList();
			var subShipmentsToDetachList = new List<ForwardingShipment>();

			if (!CheckDetachMasterSub(currentConsol, selectedShipmentsList, subShipmentsToDetachList, out var preventSubShipmentsFromBeingAddedToShipmentsGrid))
			{
				return;
			}

			var detachResult = Dashboard.TryDetach(
				currentConsol,
				selectedShipmentsList.Concat(subShipmentsToDetachList),
				preventSubShipmentsFromBeingAddedToShipmentsGrid ? subShipmentsToDetachList : null);

			if (detachResult.HasErrors)
			{
				Globals.Message.ShowError(detachResult.Errors);
			}

			UpdateValuesFromConsolForBinding(currentConsol);
			UpdateActionButtonsStatus();
		}

