		bool forceClose = false;

		protected override void OnClosing(CancelEventArgs e)
		{
			base.OnClosing(e);
			if (!forceClose && !ShouldContinueWithClose())
			{
				e.Cancel = true;
			}
		}

		bool ShouldContinueWithClose()
		{
			bool shouldContinueWithClose = true;

			if (Dashboard.HasUnsavedChanges)
			{
				var caption = Res.GetString("a4ae1b30-ff4c-4370-8110-6f509a527485", "Cancel changes");
				var message = Res.GetString("6a4886bb-df75-4e7d-b735-0f43c63de884", "Planning Board has unsaved changes. Do you want to cancel them and close the form?");

				var dialogResult = Globals.Message.Show(message, caption, MessageBoxButtons.YesNo, MessageBoxIcon.Question, DialogResult.No);
				if (dialogResult == DialogResult.No)
				{
					shouldContinueWithClose = false;
				}
			}

			return shouldContinueWithClose;
		}

		#endregion

		#region Save/Save and Close

		void SaveButton_Click(object sender, EventArgs e)
		{
			TrySave();
		}

		void SaveAndCloseButton_Click(object sender, EventArgs e)
		{
			TrySave();

			ForceCloseForm();
		}

		void TrySave()
		{
			var saveResult = Dashboard.Save();

			if (saveResult.IsEmpty)
			{
				return;
			}

			var messageBuilder = new StringBuilder();
			var successfullySavedMessage = ListConsolHumanReadableNames(
					Res.GetString("50686014-cf1d-4a8a-bb6a-2033c75a995b", "The following consol(s) have been successfully saved:"),
					saveResult.Saved);

			if (!string.IsNullOrEmpty(successfullySavedMessage))
			{
				messageBuilder.AppendLine(successfullySavedMessage);
			}

			var unsavedMessage = ListConsolHumanReadableNames(
					Res.GetString("2cac8965-8c4f-409a-862e-d6a34d96b3a7", "The following consol(s) have not been saved due to validation/concurrency errors:"),
					saveResult.Unsaved,
					AttachNotificationsExcludingConcurrencyErrorMessages);

			if (!string.IsNullOrEmpty(unsavedMessage))
			{
				messageBuilder.AppendLine(unsavedMessage);
			}

			if (saveResult.AllConsolsHaveBeenSaved)
			{
				Globals.Message.ShowInformation(messageBuilder.ToString().TrimEnd());
			}
			else
			{
				messageBuilder.AppendLine(Res.GetString("959cedb8-29c6-43ef-b83c-26a35d82c446", "Do you want the system to open unsaved consol(s) one by one so you can correct the errors manually?"));
				messageBuilder.AppendLine();
				messageBuilder.AppendLine(Res.GetString("fb97e853-0729-4199-a5a1-3118ca426ec7", "Select 'Yes' if you want the system to open unsaved consol(s) one by one"));
				messageBuilder.AppendLine(Res.GetString("e3b888ad-dce3-46db-a5e5-ad5ea55babec", "Select 'No'  if you want to leave it 'as is'; consol(s) in question would not be saved"));

				var dialogResult = ShowConfirmationDialog(messageBuilder.ToString().TrimEnd());
				if (dialogResult == DialogResult.Yes)
				{
					PresentUnsavedConsolsToUserOneByOne(saveResult.Unsaved);
				}
			}

			UpdateActionButtonsStatus();
		}

		void PresentUnsavedConsolsToUserOneByOne(IEnumerable<DashboardConsolSnapshot> unsavedConsolSnapshots)
		{
			var processedConsolPKs = new List<ZGuid>();
			foreach (var snapshot in unsavedConsolSnapshots)
			{
				RecreateConsolShipmentConfigurationAndShowConsolForm(snapshot);

				processedConsolPKs.Add(snapshot.ConsolPK);

				var remainingConsolsMessage = ListConsolHumanReadableNames(
					Res.GetString("7c301867-f120-4da1-9ab5-683e7a355f6a", "The following consols are not yet processed:"),
					unsavedConsolSnapshots.Where(unsavedSnapshots => !processedConsolPKs.Contains(unsavedSnapshots.ConsolPK)));

				if (!string.IsNullOrEmpty(remainingConsolsMessage))
				{
					remainingConsolsMessage += System.Environment.NewLine;
					remainingConsolsMessage += Res.GetString("0ea04b23-e3d5-4c01-832f-615629e21af0", "Do you want to continue?");

					var dialogResult = ShowConfirmationDialog(remainingConsolsMessage);
					if (dialogResult == DialogResult.No)
					{
						break;
					}
				}
			}
		}

		void RecreateConsolShipmentConfigurationAndShowConsolForm(DashboardConsolSnapshot consolSnapshot)
		{
			if (consolSnapshot != null)
			{
				if (consolSnapshot.State == DashboardConsolSnapshot.SnapshotState.ModifiedByAnotherUser)
				{
					var conflictErrorMessage = ListConsolConflictErrors(consolSnapshot);
					Globals.Message.Show(
						conflictErrorMessage,
						Res.GetString("799576ea-95c1-4608-8d1e-7119b3e835a6", "Concurrency Conflicts"),
						MessageBoxButtons.OK,
						MessageBoxIcon.Error,
						DialogResult.OK);
				}

				var controller = ZControllerFactory.Create(ControllerIDs.JobConsol);

				var consolReloaded = controller.Factory.Load<ForwardingConsol>(consolSnapshot.ConsolPK);
				if (consolReloaded != null)
				{
					Dashboard.RecreateShipmentConfiguration(consolReloaded, consolSnapshot.ShipmentPKs);

					consolReloaded.MarkAsNeedingValidationIncludingChildren();

					controller.ShowChildrenAsDialog = true;
					controller.ShowEditForm(consolReloaded);

					bool consolHasBeenSavedByUser = !consolReloaded.HasChanges;
					if (consolHasBeenSavedByUser)
					{
						Dashboard.RemoveCapturedSnapshot(consolReloaded);
						Dashboard.ReloadDashboardConsol(consolReloaded);
					}
				}
			}
		}

		string ListConsolConflictErrors(DashboardConsolSnapshot consolSnapshot)
		{
			var messageBuilder = new StringBuilder();

			messageBuilder.AppendLine(Res.GetString("49aa1478-379f-4d09-ab11-66fa41092acb",
				"Please resolve {0} Shipments with conflicts for {1}:",
				consolSnapshot.Notifications.Count(),
				consolSnapshot.ConsolHumanReadableName));

			foreach (var notification in consolSnapshot.Notifications)
			{
				messageBuilder.AppendLine(notification.Message);
			}

			return messageBuilder.ToString();
		}

		string ListConsolHumanReadableNames(string information, IEnumerable<DashboardConsolSnapshot> consolSnapshots, Func<DashboardConsolSnapshot, ZString> attachInfo = null)
		{
			if (consolSnapshots == null || !consolSnapshots.Any())
			{
				return string.Empty;
			}

			var messageBuilder = new StringBuilder();
			messageBuilder.AppendLine(information);
			messageBuilder.AppendLine();

			foreach (var consolHumanReadableName in consolSnapshots.Select(snapshot => attachInfo == null ? snapshot.ConsolHumanReadableName : attachInfo(snapshot)))
			{
				messageBuilder.AppendLine(consolHumanReadableName);
			}

			return messageBuilder.ToString();
		}

		ZString AttachNotificationsExcludingConcurrencyErrorMessages(DashboardConsolSnapshot snapshot)
		{
			return snapshot.State == DashboardConsolSnapshot.SnapshotState.ModifiedByAnotherUser
				? snapshot.ConsolHumanReadableName
				: AttachNotifications(snapshot);
		}

		ZString AttachNotifications(DashboardConsolSnapshot snapshot)
		{
			return snapshot.ConsolHumanReadableName +
				(snapshot.Notifications.Count() > 1 ? System.Environment.NewLine : string.Empty) +
				string.Join(System.Environment.NewLine, snapshot.Notifications.Select(notification => " - " + notification.Message));
		}

		DialogResult ShowConfirmationDialog(string message)
		{
			var dialogResult = Globals.Message.Show(
				message,
				Res.GetString("6baf3c4c-3f63-4293-a9c3-c7de03877cd3", "Confirm"),
				MessageBoxButtons.YesNo,
				MessageBoxIcon.Question,
				DialogResult.Yes);

			return dialogResult;
		}

		#endregion

		#region Master/Lead shipments and sub-shipments

		bool CheckAttachMasterSub(ForwardingConsol consol, List<ForwardingShipment> shipmentsToAttach)
		{
			var shipmentsToRemove = new List<ForwardingShipment>();
			var subShipmentsToCheck = new List<ForwardingShipment>();
			var checkMessageList = new List<string>();

			foreach (ForwardingShipment shipment in shipmentsToAttach)
			{
				var master = (ForwardingShipment)shipment.CoLoadMasterShipment;
				if (master != null)
				{
					if (!shipmentsToAttach.Any(s => s.PK == master.PK) && !master.Consols.Contains(consol))
					{
						checkMessageList.Add(Res.GetString("EC61E6A9-AF74-4A9F-9D27-E70635DF819F",
														   "{0} is a sub-shipment of master/lead {1}",
														   shipment.JS_UniqueConsignRef,
														   master.JS_UniqueConsignRef));

						subShipmentsToCheck.Add(shipment);
					}
				}
			}

			if (subShipmentsToCheck.Count > 0)
			{
				checkMessageList.Sort();

				var message = Res.GetString("95dd2ada-114d-4f68-9e6e-89a4f5a6b26d",
												"The shipments that you are trying to attach are sub-shipments:\r\n{0}\r\n\r\nOnly these shipments, without their masters, will be attached to {1} consol.\r\n\r\nIf you would like to attach these shipments, their masters/leads and all sub-shipments of their masters/leads to this consol, you need to attach the master/lead shipments to this consol instead.\r\n\r\nPress [Yes] if you would like to continue.\r\nPress [No] if you would like to skip the above listed shipments and attach all other selected shipments.\r\nPress [Cancel] to cancel operation.",
												string.Join(System.Environment.NewLine, checkMessageList.ToArray()),
												consol.JK_UniqueConsignRef);
				var caption = Res.GetString("9fc3c5af-9d37-4194-96d7-7576e5b61a51", "Attaching Shipments...");

				var dilogResult = ShowDialogWithDefault(new ZGuid("71D7977C-CFB7-4A7C-9554-FAAB040B9FB5"), message, caption, ZMessageBoxButtons.YesNoCancel, ZMessageBoxIcon.Warning);
				switch (dilogResult)
				{
					case ZDialogResult.Yes:
						break;
					case ZDialogResult.No:
						shipmentsToRemove.AddRange(subShipmentsToCheck);
						break;
					default:
						return false;
				}
			}

			foreach (var shipment in shipmentsToRemove)
			{
				shipmentsToAttach.Remove(shipment);
			}

			return true;
		}

		bool CheckDetachMasterSub(ForwardingConsol consol, List<ForwardingShipment> shipmentsToDetach, List<ForwardingShipment> subShipmentsToDetach, out bool preventSubShipmentsFromBeingAddedToShipmentsGrid)
		{
			preventSubShipmentsFromBeingAddedToShipmentsGrid = false;

			var masterLeadShipmentsList = new List<ForwardingShipment>();
			var subShipmentsList = new List<ForwardingShipment>();

			foreach (var shipment in shipmentsToDetach)
			{
				var subShipments = new List<ForwardingShipment>();
				GetSubShipments(shipment, subShipments);

				foreach (var subShipment in subShipments.Where(item => !shipmentsToDetach.Contains(item) && item.Consols.Contains(consol)))
				{
					if (!subShipmentsList.Contains(subShipment))
					{
						subShipmentsList.Add(subShipment);
					}
					if (!masterLeadShipmentsList.Contains(shipment))
					{
						masterLeadShipmentsList.Add(shipment);
					}
				}
			}

			if (masterLeadShipmentsList.Any())
			{
				var message = Res.GetString("F21083E5-4C82-4B38-B8B5-193C125352C1",
					"The {2} {0} {1} master / lead {2} of {3}.\r\n\r\nDo you also want to detach the {4} from the consol {5}?\r\n\r\nPress [Yes] to detach the master / lead {2} and {4} from the consol.\r\nPress [No] to detach the master / lead {2} from the consol, but keep the {4} attached to the consol.\r\nPress [Cancel] to cancel the operation.",
					string.Join(", ", masterLeadShipmentsList.Select(s => s.JS_UniqueConsignRef)),
					masterLeadShipmentsList.Take(2).Count() == 1 ? "is a" : "are",
					masterLeadShipmentsList.Take(2).Count() == 1 ? "shipment" : "shipments",
					string.Join(", ", subShipmentsList.Select(s => s.JS_UniqueConsignRef)),
					subShipmentsList.Take(2).Count() == 1 ? "sub-shipment" : "sub-shipments",
					consol.JK_UniqueConsignRef);
				var caption = Res.GetString("F1E0027E-5156-4883-AEA7-C268F715F9AB", "Detaching Shipments...");

				var dialogResult = ShowDialogWithDefault(new ZGuid("D62CC65A-CDBB-4383-AFAF-F66D1CD69C5C"), message, caption, ZMessageBoxButtons.YesNoCancel, ZMessageBoxIcon.Warning);
				switch (dialogResult)
				{
					case ZDialogResult.Yes:
						subShipmentsToDetach.AddRange(subShipmentsList);

						var showSubShipmentsMessage = Res.GetString("9466716C-39A3-4240-811C-A640BA54BBED", "Do you want to show detached sub-shipments in the top left shipments grid?");
						var showSubShipmentDialogResult = ShowDialogWithDefault(new ZGuid("98966890-9287-4B44-9493-10E5D953457A"), showSubShipmentsMessage, caption, ZMessageBoxButtons.YesNo, ZMessageBoxIcon.Question);
						switch (showSubShipmentDialogResult)
						{
							case ZDialogResult.No:
								preventSubShipmentsFromBeingAddedToShipmentsGrid = true;
								break;
							default:
								break;
						}
						break;
					case ZDialogResult.No:
						break;
					default:
						return false;
				}
			}

			return true;
		}

		void GetSubShipments(ForwardingShipment shipment, List<ForwardingShipment> subShipments)
		{
			subShipments.Add(shipment);
			foreach (var subShipment in shipment.CoLoadShipments.Cast<ForwardingShipment>())
			{
				GetSubShipments(subShipment, subShipments);
			}
		}

		ZDialogResult ShowDialogWithDefault(ZGuid dialogGuid, string message, string caption, ZMessageBoxButtons buttons, ZMessageBoxIcon icon)
		{
			var dialogContext = new DialogDefaultContext(dialogGuid, caption, buttons, icon, null, showCheckboxOnly: true);
			return Globals.Message.ShowOrDefault(dialogContext, message);
		}

		#endregion
	}
